        text: "Coordinating with law enforcement also matters for accessing physical evidence gathered at the scene, such as the truck itself, before it's released back to the carrier and potentially repaired or returned to service. Prompt communication with the investigating agency about the firm's interest in preserving and inspecting physical evidence protects the client's case from a common and often irreversible evidentiary loss.",
