        type: "paragraph",
        text: "Insurers routinely request an independent medical examination in contested mental injury claims, and attorneys should prepare clients thoroughly for these evaluations, since the resulting report often plays an outsized role in how the claim is ultimately resolved. Unlike an orthopedic independent examination, which can rely heavily on objective physical findings, a psychological independent examination depends substantially on the evaluator's clinical judgment and the client's own reporting during the interview, making preparation and the client's ability to communicate their symptoms clearly and consistently especially important.",
