        type: "paragraph",
        text: "Attorneys should also scrutinize the qualifications and methodology of any independent examiner selected by the insurer, since evaluators retained repeatedly by the same insurance carrier can develop patterns in their findings that are worth investigating through prior deposition testimony or published outcome data where available, and a well-prepared cross-examination addressing potential evaluator bias can meaningfully affect how much weight a judge or hearing officer ultimately assigns to a contested independent examination report.",
