        type: "paragraph",
        text: "Coordinating these parallel claims requires careful strategic sequencing, since pursuing one remedy can sometimes affect the viability or value of the other, and attorneys without employment law expertise should consider referral relationships with employment attorneys for cases presenting this kind of overlap, ensuring the client's full range of legal options gets properly evaluated rather than being funneled exclusively through whichever practice area the initially consulted attorney happens to handle.",
