        text: "The term black box in trucking litigation generally refers to a combination of data sources rather than a single device. Engine control modules can record speed, throttle position, braking activity, and RPM data in the moments surrounding a sudden deceleration event. Event data recorders, where present, may capture similar pre-crash and crash-phase information in more detail, comparable in concept to the systems increasingly common in passenger vehicles but with data specific to commercial truck operation.",
