        text: "That history explains why legal advertising compliance focuses so heavily on truthfulness and the prevention of misleading claims specifically. Regulators recognize that someone searching for an attorney after an accident, arrest, or family crisis is often not in a strong position to carefully evaluate marketing puffery, which is precisely why the rules impose a stricter truthfulness standard on attorney advertising than applies to advertising for many ordinary consumer products.",
