        text: "Reviewing conversion rates by intake staff member, by time of day, and by lead source can reveal specific, addressable gaps — for example, leads arriving after hours converting at a much lower rate, pointing toward a need for extended intake coverage rather than additional marketing spend to compensate for a conversion problem that better staffing could solve more cost-effectively.",
