        text: "Underperforming channels deserve genuine diagnosis rather than an automatic budget cut. Sometimes a channel underperforms because of external market shifts beyond the firm's control, but often the root cause is fixable — a landing page mismatch with ad messaging, an intake process that couldn't keep pace with lead volume from that source, or targeting that drifted away from the firm's actual ideal client profile over the course of the year.",
